export const EDITOR_HTML = "<!doctype html>\n<html lang=\"it\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no\">\n<title>Tagli della Home</title>\n<style>\n/* Layout: banco di lavoro a una colonna — scelta del prodotto in alto, poi le tre cornici della Home una sotto l'altra,\n   ognuna con l'anteprima com'è nell'app, lo zoom e \"Salva\". Stessa palette blu notte dell'app Digital Gate. */\n:root {\n  --bg: #0b1120;\n  --surface: #121a2e;\n  --surface2: #1a2540;\n  --line: #26324d;\n  --ink: #e8edf7;\n  --ink2: #9aa8c4;\n  --cyan: #63d5ee;\n  --cyan-soft: rgba(99, 213, 238, .14);\n  --accent: #ff7a3d;\n  --accent-ink: #1a0b03;\n  --ok: #5fd39a;\n  --warn: #ffb86b;\n  --display: \"Chakra Petch\", \"Segoe UI\", system-ui, sans-serif;\n  --body: \"IBM Plex Sans\", system-ui, -apple-system, sans-serif;\n  color-scheme: dark;\n}\n* { box-sizing: border-box; }\nbody { background: var(--bg); color: var(--ink); font-family: var(--body); font-size: 15px; line-height: 1.45; }\n.wrap { max-width: 760px; margin: 0 auto; padding-block: 20px 60px;\n  padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px));\n  display: flex; flex-direction: column; gap: 22px; }\nh1 { font-family: var(--display); font-weight: 700; font-size: 26px; margin: 0; letter-spacing: -.2px; }\n.lead { color: var(--ink2); margin: 4px 0 0; max-width: 60ch; }\n.eyebrow { font-family: var(--display); font-weight: 600; font-size: 12px; letter-spacing: 1.6px; text-transform: uppercase; color: var(--ink2); }\n.status { font-size: 13px; color: var(--ink2); min-height: 18px; }\n.status.warn { color: var(--warn); }\n\n.chips { display: flex; flex-wrap: wrap; gap: 8px; }\n.chip { font-family: var(--display); font-weight: 600; font-size: 14px; letter-spacing: .6px; color: var(--ink);\n  background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 8px 12px; cursor: pointer;\n  display: inline-flex; align-items: center; gap: 8px; }\n.chip small { font-family: var(--body); font-weight: 500; font-size: 12px; color: var(--ink2); letter-spacing: 0; }\n.chip[aria-pressed=\"true\"] { border-color: var(--cyan); background: var(--cyan-soft); color: var(--cyan); }\n.chip .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--ok); }\n.chip:focus-visible, button:focus-visible, input:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }\n\n.sec { background: var(--surface); border: 1px solid var(--line); border-radius: 16px; padding: 16px; display: flex; flex-direction: column; gap: 14px; }\n.sec-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; }\n.sec-head h2 { font-family: var(--display); font-weight: 700; font-size: 18px; margin: 0; }\n.sec-head .rule { font-size: 13px; color: var(--ink2); }\n.saved { font-size: 12.5px; font-weight: 600; padding: 3px 8px; border-radius: 6px; background: rgba(95, 211, 154, .14); color: var(--ok); }\n.saved.changed { background: rgba(255, 184, 107, .14); color: var(--warn); }\n\n/* cornici: la zona dove si trascina */\n.frame { position: relative; overflow: hidden; background: #1a2540; touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }\n.frame.drag { cursor: grabbing; }\n.frame img { position: absolute; left: 0; top: 0; max-width: none; transform-origin: 0 0; pointer-events: none; }\n.guides { position: absolute; inset: 0; pointer-events: none; opacity: 0; transition: opacity .15s; }\n.frame.drag .guides, .frame:hover .guides { opacity: 1; }\n.guides::before, .guides::after { content: \"\"; position: absolute; background: rgba(255, 255, 255, .35); }\n.guides::before { left: 33.33%; right: 33.33%; top: 0; bottom: 0; border-left: 1px solid rgba(255,255,255,.35); border-right: 1px solid rgba(255,255,255,.35); background: none; }\n.guides::after { top: 33.33%; bottom: 33.33%; left: 0; right: 0; border-top: 1px solid rgba(255,255,255,.35); border-bottom: 1px solid rgba(255,255,255,.35); background: none; }\n\n/* In evidenza: come HeroSlide */\n.hero { width: 100%; max-width: 440px; aspect-ratio: 1.313; border-radius: 16px; }\n.mini-f.hero { border-radius: 8px; }\n.hero .fade { position: absolute; inset: 0; pointer-events: none;\n  background: linear-gradient(to bottom, rgba(11,17,32,.15) 0%, rgba(11,17,32,.15) 18%, rgba(11,17,32,.25) 35%, rgba(11,17,32,.91) 66%, #0b1120 100%); }\n.hero .over { position: absolute; inset: 0; padding: 15px; display: flex; flex-direction: column; justify-content: space-between; pointer-events: none; }\n.hero .top { display: flex; justify-content: space-between; align-items: flex-start; }\n.glass { border: 1px solid rgba(232,237,247,.17); background: rgba(11,17,32,.86); border-radius: 6px; padding: 4px 8px;\n  font-family: var(--display); font-weight: 600; font-size: 10.5px; letter-spacing: 1.4px; color: var(--ink); }\n.date { border-radius: 9px; text-align: center; padding: 5px 8px; }\n.date b { display: block; font-size: 20px; line-height: 22px; letter-spacing: 0; }\n.date span { font-size: 9.5px; color: #a3b1cb; }\n.hero .eb { font-family: var(--display); font-weight: 600; font-size: 10.5px; letter-spacing: 1.2px; color: var(--cyan); text-transform: uppercase; }\n.hero .nm { font-family: var(--display); font-weight: 700; font-size: 29px; line-height: 32px; margin: 3px 0 12px; color: #f4f7fd; }\n.hero .btn { height: 44px; border-radius: 10px; background: var(--accent); color: var(--accent-ink); font-weight: 600; font-size: 14px;\n  display: flex; align-items: center; justify-content: center; }\n\n/* Set da completare: come GoalCard */\n.goal { display: flex; align-items: center; gap: 12px; padding: 13px; border-radius: 14px; border: 1px solid var(--line); background: var(--bg); max-width: 440px; position: relative; }\n.goal::before { content: \"\"; position: absolute; left: -1px; top: 18px; bottom: 18px; width: 3px; border-radius: 2px; background: var(--cyan); }\n.cover { width: 104px; aspect-ratio: 65 / 91; border-radius: 10px; flex: none; }\n.goal .txt { flex: 1; min-width: 0; }\n.tag { display: inline-block; border-radius: 4px; padding: 1px 5px; background: var(--cyan-soft); color: var(--cyan); font-family: var(--display); font-weight: 600; font-size: 11px; letter-spacing: .6px; }\n.goal .nm { font-family: var(--display); font-weight: 700; font-size: 16px; margin: 4px 0 8px; }\n.bar { height: 5px; border-radius: 3px; background: var(--surface2); overflow: hidden; }\n.bar i { display: block; height: 100%; width: 34%; background: var(--cyan); }\n.goal .miss { color: var(--cyan); font-weight: 600; font-size: 12.8px; margin-top: 9px; }\n\n/* All'orizzonte: come HorizonLine */\n.hz { width: 190px; }\n.hz .when { font-family: var(--display); font-weight: 700; font-size: 12px; letter-spacing: .6px; color: var(--cyan); margin-bottom: 6px; display: flex; align-items: center; gap: 6px; }\n.hz .when::before { content: \"\"; width: 10px; height: 10px; border-radius: 50%; background: var(--cyan); }\n.square { width: 190px; aspect-ratio: 1; border-radius: 12px; }\n.hz .cd { font-family: var(--display); font-weight: 600; font-size: 10.5px; letter-spacing: .6px; color: var(--cyan); margin-top: 7px; }\n.hz .nm { font-family: var(--display); font-weight: 600; font-size: 13px; }\n\n.controls { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }\n.controls label { font-size: 13px; color: var(--ink2); }\n.controls input[type=range] { flex: 1; min-width: 140px; accent-color: var(--cyan); }\n.zv { font-variant-numeric: tabular-nums; font-size: 13px; color: var(--ink2); width: 44px; }\nbutton.b { font-family: var(--body); font-weight: 600; font-size: 14px; border-radius: 10px; padding: 9px 14px; cursor: pointer; border: 1px solid var(--line); background: var(--surface2); color: var(--ink); }\nbutton.b.pri { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }\nbutton.b:disabled { opacity: .45; cursor: default; }\n.hint { font-size: 12.5px; color: var(--ink2); }\n\n.add { display: flex; flex-direction: column; gap: 10px; }\n.add .row { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }\n.add input[type=text] { font: inherit; background: var(--bg); color: var(--ink); border: 1px solid var(--line); border-radius: 10px; padding: 9px 12px; min-width: 0; flex: 1 1 140px; }\n.empty { color: var(--ink2); padding: 24px; text-align: center; border: 1px dashed var(--line); border-radius: 14px; }\n\n/* telefoni e anteprime piccole (In evidenza) */\n.phones { display: flex; flex-wrap: wrap; gap: 6px; }\n.chip.ph { font-size: 13px; padding: 6px 10px; }\n.minis { display: flex; flex-wrap: wrap; gap: 14px; align-items: flex-end; }\n.mini { display: flex; flex-direction: column; gap: 5px; }\n.mini-f { border-radius: 8px; max-width: 100%; }\n.mini-nm { position: absolute; left: 7px; bottom: 6px; right: 7px; font-family: var(--display); font-weight: 700; font-size: 11px; color: #f4f7fd; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n\n/* D-pad e zoom */\n.tools { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }\n.pad { display: grid; grid-template-columns: repeat(3, 44px); grid-template-rows: repeat(3, 44px); gap: 4px; flex: none; }\n.pad-e { display: block; }\n.pad-b { font: 600 17px/1 var(--body); color: var(--ink); background: var(--surface2); border: 1px solid var(--line); border-radius: 10px; cursor: pointer;\n  display: flex; align-items: center; justify-content: center; touch-action: none; user-select: none; -webkit-user-select: none; }\n.pad-b:active { background: var(--cyan-soft); border-color: var(--cyan); color: var(--cyan); }\n.pad-c { font-size: 12px; color: var(--ink2); }\n.tools-r { display: flex; flex-direction: column; gap: 10px; flex: 1; min-width: 180px; }\n.zpad { display: flex; align-items: center; gap: 8px; }\n.zpad .pad-b { width: 44px; height: 40px; font-size: 20px; }\n.zpad .zv { width: 52px; text-align: center; }\n.tools-r input[type=range] { width: 100%; accent-color: var(--cyan); }\n.tools-r .b.pri { align-self: flex-start; }\n.pad-b:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }\n\n/* catena: telefoni collegati o sganciati */\n.chain-row { display: flex; align-items: center; gap: 10px; flex-basis: 100%; margin-top: 4px; }\n.chain { width: 40px; height: 36px; flex: none; display: flex; align-items: center; justify-content: center; border-radius: 10px; cursor: pointer;\n  border: 1px solid var(--cyan); background: var(--cyan-soft); color: var(--cyan); }\n.chain.off { border-color: var(--warn); background: rgba(255, 184, 107, .14); color: var(--warn); }\n.chain:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }\n.chip.ph.solo { border-style: dashed; border-color: var(--warn); }\n.chip.ph.solo[aria-pressed=\"true\"] { color: var(--warn); background: rgba(255, 184, 107, .14); border-style: solid; }\n.mini-f.cur { outline: 2px solid var(--cyan); outline-offset: 2px; }\n\n/* indicatore in pixel */\n.meter { border: 1px solid var(--line); border-radius: 10px; padding: 9px 11px; background: var(--bg); display: flex; flex-direction: column; gap: 4px; font-size: 13px; }\n.m-h { font-family: var(--display); font-weight: 600; font-size: 10.5px; letter-spacing: 1.2px; text-transform: uppercase; color: var(--ink2); }\n.m-move { color: var(--ink); font-variant-numeric: tabular-nums; margin-bottom: 4px; }\n.m-grid { display: grid; grid-template-columns: repeat(4, auto); gap: 4px 12px; justify-content: start; color: var(--ink2); font-variant-numeric: tabular-nums; }\n.m-grid b { color: var(--ink); font-weight: 600; }\n.m-note { color: var(--ink2); font-size: 11.5px; margin-top: 2px; }\n@media (max-width: 420px) { .m-grid { grid-template-columns: repeat(2, auto); } }\n@media (prefers-reduced-motion: reduce) { .guides { transition: none; } }\n\n/* [hidden] vince sempre sulle regole di display delle classi */\n[hidden] { display: none !important; }\n.view { display: flex; flex-direction: column; gap: 22px; }\n.tabs { display: flex; gap: 8px; }\n.tabs .chip { font-size: 15px; padding: 10px 18px; }\n.sel { font-family: var(--display); font-weight: 600; font-size: 15px; letter-spacing: .3px; color: var(--ink); background: var(--surface);\n  border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; width: 100%; max-width: 460px; cursor: pointer; }\n.sel:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }\n\n/* confronto: per serie, poi per tipo di banner, con scorrimento a destra */\n.cmp-wrap { display: flex; flex-direction: column; gap: 18px; }\n#cmp { display: flex; flex-direction: column; gap: 28px; }\n.cmp-series { display: flex; flex-direction: column; gap: 26px; padding: 18px 16px 8px; border: 1px solid var(--line); border-radius: 16px; background: var(--surface); }\n.cmp-cat { font-family: var(--display); font-weight: 700; font-size: 16px; letter-spacing: 1.2px; text-transform: uppercase; color: var(--cyan); }\n.cmp-cat small { font-family: var(--body); font-weight: 500; font-size: 12.5px; letter-spacing: 0; text-transform: none; color: var(--ink2); margin-left: 8px; }\n.cmp-type { display: flex; flex-direction: column; gap: 10px; }\n.cmp-tname { font-family: var(--display); font-weight: 600; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: var(--ink2); }\n/* immagini allineate in alto: le scritte sotto non le spostano */\n.cmp-scroll { display: flex; gap: 18px; align-items: flex-start; overflow-x: auto; padding-bottom: 14px; scroll-snap-type: x proximity; scrollbar-width: thin; -webkit-overflow-scrolling: touch; }\n.cmp-cell { display: flex; flex-direction: column; gap: 7px; flex: none; scroll-snap-align: start; }\n.cmp-box { position: relative; overflow: hidden; border-radius: 9px; background: #1a2540; border: 1px solid var(--line); }\n.cmp-box img { position: absolute; max-width: none; pointer-events: none; }\n.cmp-box.none { display: flex; align-items: center; justify-content: center; padding: 6px; text-align: center; border-style: dashed; color: var(--ink2); font-size: 11.5px; background: transparent; }\n/* scritte larghe quanto l'immagine, una riga ciascuna (puntini se non ci stanno) */\n.cmp-cap { font-size: 12px; color: var(--ink2); line-height: 17px; min-width: 96px; }\n.cmp-cap div { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.cmp-cap b { color: var(--ink); font-weight: 600; }\n.cmp-cap .st { font-size: 11.5px; }\n</style>\n</head>\n<body>\n\n<div class=\"wrap\">\n  <header>\n    <div class=\"eyebrow\">Digital Gate · Home</div>\n    <h1>Tagli della Home</h1>\n    <p class=\"lead\">Scegli un prodotto, sposta l'immagine dentro ogni riquadro e regola lo zoom. Con \"Salva\" il taglio va sul tuo GitHub e arriva nell'app di tutti in pochi minuti.</p>\n  </header>\n\n  <div class=\"tabs\" role=\"group\" aria-label=\"Vista\">\n    <button type=\"button\" class=\"chip\" id=\"tabEdit\" aria-pressed=\"true\">Taglia</button>\n    <button type=\"button\" class=\"chip\" id=\"tabCmp\" aria-pressed=\"false\">Confronto</button>\n  </div>\n\n  <div class=\"view\" id=\"viewEdit\">\n    <section aria-labelledby=\"pk\">\n      <div class=\"eyebrow\" id=\"pk\" style=\"margin-bottom:10px\">Prodotto</div>\n      <div id=\"chips\"><span class=\"hint\">Caricamento delle immagini…</span></div>\n      <div class=\"status\" id=\"status\" role=\"status\"></div>\n    </section>\n\n    <div id=\"editor\"></div>\n\n    <section class=\"sec add\" id=\"addBox\" hidden aria-labelledby=\"addT\">\n      <div class=\"sec-head\"><h2 id=\"addT\">Aggiungi un'immagine</h2><span class=\"rule\">Per un prodotto nuovo o per sostituirne una</span></div>\n      <div class=\"row\">\n        <input type=\"text\" id=\"addCode\" placeholder=\"Codice, es. EX14\" autocomplete=\"off\" aria-label=\"Codice del prodotto\">\n        <input type=\"text\" id=\"addName\" placeholder=\"Nome, es. Malevolent VII\" autocomplete=\"off\" aria-label=\"Nome del prodotto\">\n      </div>\n      <div class=\"row\">\n        <input type=\"file\" id=\"addFile\" accept=\"image/png,image/jpeg,image/webp\" aria-label=\"Immagine\">\n        <button class=\"b pri\" id=\"addBtn\" type=\"button\">Carica</button>\n      </div>\n      <div class=\"status\" id=\"addStatus\" role=\"status\"></div>\n    </section>\n  </div>\n\n  <div class=\"view\" id=\"viewCmp\" hidden>\n    <section class=\"cmp-wrap\" aria-labelledby=\"cmpT\">\n      <div class=\"sec-head\"><h2 id=\"cmpT\">Tutto quello che hai caricato</h2><span class=\"rule\">Per serie e tipo di banner · scorri a destra</span></div>\n      <div id=\"cmp\"></div>\n    </section>\n  </div>\n</div>\n\n<script>\n// Ponte con l'app (rn/src/app/tagli.tsx): stessa interfaccia della pagina su claude.ai (db e assets), ma i dati\n// arrivano dall'app e i salvataggi passano all'app, che li scrive sul ramo home-art di GitHub.\n(() => {\n  const RN = window.ReactNativeWebView;\n  let n = 0, DATA = null;\n  const wait = {}, subs = {}, LOCAL = {};\n  const post = (m) => RN && RN.postMessage(JSON.stringify(m));\n  const call = (m) => new Promise((ok, ko) => { const id = ++n; wait[id] = { ok, ko }; post(Object.assign({ id }, m)); });\n  const snap = (c) => ({ metadata: { fromCache: false }, docs: Object.keys((DATA && DATA[c]) || {}).map((id) => ({ id, data: () => DATA[c][id] })) });\n  window.__recv = (m) => {\n    if (m.t === \"data\") { DATA = m.data; Object.keys(subs).forEach((c) => subs[c].forEach((f) => f(snap(c)))); return; }\n    const w = wait[m.id]; if (!w) return; delete wait[m.id];\n    if (m.err) w.ko(new Error(m.err)); else w.ok(m.res);\n  };\n  window.BLOB = (id) => LOCAL[id] || ((window.__BLOB || \"img/\") + encodeURIComponent(id));\n  const db = {\n    collection: (c) => ({ onSnapshot: (cb) => { (subs[c] = subs[c] || []).push(cb); if (DATA) cb(snap(c)); return () => {}; } }),\n    doc: (p) => ({ set: (body) => call({ t: \"set\", path: p, body }), delete: () => call({ t: \"del\", path: p }) }),\n  };\n  // immagine nuova: ridotta a 1600 px sul lato lungo e convertita in WebP (o JPEG) prima di mandarla all'app\n  const assets = { upload: async (file, code) => {\n    const url = URL.createObjectURL(file);\n    const im = await new Promise((ok, ko) => { const i = new Image(); i.onload = () => ok(i); i.onerror = () => ko(new Error(\"immagine non leggibile\")); i.src = url; });\n    const k = Math.min(1, 1600 / Math.max(im.naturalWidth, im.naturalHeight));\n    const w = Math.round(im.naturalWidth * k), h = Math.round(im.naturalHeight * k);\n    const cv = document.createElement(\"canvas\"); cv.width = w; cv.height = h; cv.getContext(\"2d\").drawImage(im, 0, 0, w, h);\n    URL.revokeObjectURL(url);\n    let du = cv.toDataURL(\"image/webp\", 0.9), ext = \"webp\";\n    if (du.indexOf(\"data:image/webp\") !== 0) { du = cv.toDataURL(\"image/jpeg\", 0.9); ext = \"jpg\"; }\n    const id = await call({ t: \"upload\", code: code || \"\", b64: du.slice(du.indexOf(\",\") + 1), ext });\n    LOCAL[id] = du;\n    return { id, w, h };\n  } };\n  window.claude = { use: async (x) => (x === \"db\" ? db : x === \"assets\" ? assets : null) };\n  post({ t: \"ready\" });\n})();\n</script>\n<script>\n(() => {\n  // Riquadri dell'app (stesse proporzioni di rn/src/home.tsx)\n  const SECS = [\n    { id: \"hero\", name: \"In evidenza\", ar: 1.313, rule: \"Zoom forte, soggetto al centro e sollevato sopra il nome. Il riquadro cambia forma con la larghezza del telefono: controlla le anteprime in fondo.\" },\n    { id: \"cover\", name: \"Set da completare\", ar: 65 / 91, rule: \"Zoom medio, testa e busto, niente scritte tagliate\" },\n    { id: \"square\", name: \"All'orizzonte\", ar: 1, rule: \"Riquadro quadrato della linea del tempo\" },\n  ];\n  const ZMAX = 3.5;\n  let db = null, assets = null;\n  let IMGS = {};   // code -> {code, name, asset, w, h}\n  let CUTS = {};   // code__sec -> {x0,y0,x1,y1, asset}\n  let cur = null;  // codice scelto\n  const state = {}; // sec -> {cx, cy, z, dirty}\n  const $ = (id) => document.getElementById(id);\n  const status = (t, warn) => { const s = $(\"status\"); s.textContent = t || \"\"; s.classList.toggle(\"warn\", !!warn); };\n\n  // ---- geometria: cx, cy = centro della vista in frazioni dell'immagine; z = 1 riempie il riquadro\n  function viewSize(img, ar, z) { // larghezza/altezza della vista in pixel dell'immagine\n    let w, h;\n    if (img.w / img.h > ar) { h = img.h; w = h * ar; } else { w = img.w; h = w / ar; }\n    return { w: w / z, h: h / z };\n  }\n  function clamp(img, ar, st) {\n    const v = viewSize(img, ar, st.z);\n    const hx = v.w / 2 / img.w, hy = v.h / 2 / img.h;\n    st.cx = Math.min(1 - hx, Math.max(hx, st.cx));\n    st.cy = Math.min(1 - hy, Math.max(hy, st.cy));\n  }\n  function rectOf(img, ar, st) {\n    const v = viewSize(img, ar, st.z);\n    const x0 = st.cx * img.w - v.w / 2, y0 = st.cy * img.h - v.h / 2;\n    return { x0, y0, x1: x0 + v.w, y1: y0 + v.h };\n  }\n  // In evidenza: nell'app il riquadro è largo (schermo − 50) e alto 276, quindi cambia forma da telefono a telefono.\n  // Il taglio salvato fissa centro e altezza (sul telefono medio); sugli altri si vede più o meno ai lati,\n  // sempre con lo stesso centro, come fa l'app con l'immagine preparata da tools/apply_home_cuts.py.\n  const PHONES = [\n    { id: \"s\", name: \"Piccolo\", dp: 360 },\n    { id: \"m\", name: \"Medio\", dp: 411 },\n    { id: \"l\", name: \"Grande\", dp: 448 },\n    { id: \"f\", name: \"Pieghevole aperto\", dp: 600 },\n  ];\n  const heroAr = (dp) => (dp - 50) / 276;\n  let phone = \"m\";\n  function shownRect(img, sec, st, ar) {\n    const ref = rectOf(img, sec.ar, st);\n    if (sec.id !== \"hero\" || !ar || Math.abs(ar - sec.ar) < 1e-3) return ref;\n    const cx = st.cx * img.w, cy = st.cy * img.h;\n    let h = ref.y1 - ref.y0, w = h * ar;\n    const lim = 2 * Math.min(cx, img.w - cx);\n    if (w > lim) { w = lim; h = w / ar; }\n    return { x0: cx - w / 2, y0: cy - h / 2, x1: cx + w / 2, y1: cy + h / 2 };\n  }\n  function fromRect(img, ar, r) { // rettangolo salvato (frazioni) -> stato\n    const x0 = r.x0 * img.w, x1 = r.x1 * img.w, y0 = r.y0 * img.h, y1 = r.y1 * img.h;\n    const full = viewSize(img, ar, 1);\n    return { cx: (x0 + x1) / 2 / img.w, cy: (y0 + y1) / 2 / img.h, z: Math.max(1, Math.min(ZMAX, full.w / (x1 - x0))) };\n  }\n\n  // ---- scelta del prodotto: menu a tendina, raggruppato per serie\n  function renderChips() {\n    const codes = Object.keys(IMGS).sort(cmpSort);\n    const box = $(\"chips\");\n    if (!codes.length) { box.textContent = \"\"; const s = document.createElement(\"span\"); s.className = \"hint\"; s.textContent = \"Nessuna immagine ancora.\"; box.append(s); return; }\n    let sel = box.querySelector(\"select\");\n    if (!sel) {\n      box.textContent = \"\";\n      sel = document.createElement(\"select\"); sel.id = \"prodSel\"; sel.className = \"sel\"; sel.setAttribute(\"aria-label\", \"Prodotto\");\n      sel.onchange = () => { cur = sel.value; renderChips(); renderEditor(); };\n      box.append(sel);\n    }\n    sel.textContent = \"\";\n    let grp = null, lastCat = null;\n    for (const c of codes) {\n      const cat = seriesOf(c);\n      if (cat !== lastCat) { grp = document.createElement(\"optgroup\"); grp.label = \"Serie \" + cat; sel.append(grp); lastCat = cat; }\n      const n = SECS.filter((s) => CUTS[c + \"__\" + s.id] && CUTS[c + \"__\" + s.id].asset === IMGS[c].asset).length;\n      const o = document.createElement(\"option\"); o.value = c;\n      o.textContent = c + (IMGS[c].name ? \" · \" + IMGS[c].name : \"\") + (n ? \" · tagli \" + n + \"/\" + SECS.length : \"\");\n      grp.append(o);\n    }\n    if (cur) sel.value = cur;\n  }\n\n  // ---- editor: le tre cornici\n  function frameFor(sec, img) {\n    const f = document.createElement(\"div\");\n    f.className = \"frame \" + sec.id;\n    f.tabIndex = 0;\n    f.setAttribute(\"role\", \"img\");\n    f.setAttribute(\"aria-label\", \"Inquadratura per \" + sec.name + \". Trascina per spostare, frecce per spostare, + e − per lo zoom.\");\n    const im = document.createElement(\"img\");\n    im.alt = \"\"; im.draggable = false; im.src = BLOB(img.asset);\n    const g = document.createElement(\"div\"); g.className = \"guides\";\n    f.append(im, g);\n    return f;\n  }\n  function overlay(sec, img, frame) {\n    const name = img.name || img.code;\n    if (sec.id === \"hero\") {\n      const fade = document.createElement(\"div\"); fade.className = \"fade\";\n      const o = document.createElement(\"div\"); o.className = \"over\";\n      o.innerHTML = '<div class=\"top\"><span class=\"glass\">USCITO DI RECENTE</span><span class=\"glass date\"><b>04</b><span>AGO</span></span></div><div><div class=\"eb\"></div><div class=\"nm\"></div><div class=\"btn\">Scopri il prodotto →</div></div>';\n      o.querySelector(\".eb\").textContent = img.code + \" · prodotto\";\n      o.querySelector(\".nm\").textContent = name;\n      frame.append(fade, o);\n      return frame;\n    }\n    if (sec.id === \"cover\") {\n      const card = document.createElement(\"div\"); card.className = \"goal\";\n      const t = document.createElement(\"div\"); t.className = \"txt\";\n      t.innerHTML = '<span class=\"tag\"></span><div class=\"nm\"></div><div class=\"bar\"><i></i></div><div class=\"miss\">Ti mancano 104 carte</div>';\n      t.querySelector(\".tag\").textContent = img.code; t.querySelector(\".nm\").textContent = name;\n      card.append(frame, t);\n      return card;\n    }\n    const hz = document.createElement(\"div\"); hz.className = \"hz\";\n    hz.innerHTML = '<div class=\"when\">DIC 2026</div>';\n    hz.append(frame);\n    const cd = document.createElement(\"div\"); cd.className = \"cd\"; cd.textContent = img.code;\n    const nm = document.createElement(\"div\"); nm.className = \"nm\"; nm.textContent = name;\n    hz.append(cd, nm);\n    return hz;\n  }\n  function paint(sec, img, frame, ar) {\n    const st = state[sec.id];\n    clamp(img, sec.ar, st);\n    const r = shownRect(img, sec, st, ar);\n    const W = frame.clientWidth, s = W / (r.x1 - r.x0);\n    const im = frame.querySelector(\"img\");\n    im.style.width = img.w + \"px\"; im.style.height = img.h + \"px\";\n    im.style.transform = \"translate(\" + (-r.x0 * s) + \"px,\" + (-r.y0 * s) + \"px) scale(\" + s + \")\";\n  }\n  // tasto che ripete finché resta premuto (prima un passo, poi sempre più veloce)\n  function holdButton(label, title, act) {\n    const b = document.createElement(\"button\");\n    b.type = \"button\"; b.className = \"pad-b\"; b.textContent = label; b.title = title; b.setAttribute(\"aria-label\", title);\n    let t = null, n = 0;\n    const stop = () => { clearTimeout(t); t = null; };\n    const tick = () => { n++; act(n > 12 ? 3 : 1); t = setTimeout(tick, n > 6 ? 35 : 70); };\n    b.addEventListener(\"pointerdown\", (e) => { e.preventDefault(); b.setPointerCapture(e.pointerId); n = 0; act(1); t = setTimeout(tick, 350); });\n    b.addEventListener(\"pointerup\", stop); b.addEventListener(\"pointercancel\", stop); b.addEventListener(\"lostpointercapture\", stop);\n    b.addEventListener(\"keydown\", (e) => { if (e.key === \"Enter\" || e.key === \" \") { e.preventDefault(); act(1); } });\n    return b;\n  }\n\n  const CHAIN = '<svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 13a5 5 0 0 0 7.07 0l3-3a5 5 0 0 0-7.07-7.07l-1.5 1.5\"/><path d=\"M14 11a5 5 0 0 0-7.07 0l-3 3a5 5 0 0 0 7.07 7.07l1.5-1.5\"/></svg>';\n  const CHAIN_OFF = '<svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 17H7A5 5 0 0 1 7 7h2\"/><path d=\"M15 7h2a5 5 0 0 1 4 8\"/><path d=\"M8 12h3\"/><path d=\"M3 3l18 18\"/></svg>';\n\n  function renderEditor() {\n    const ed = $(\"editor\");\n    ed.textContent = \"\";\n    if (!cur || !IMGS[cur]) { const e = document.createElement(\"div\"); e.className = \"empty\"; e.textContent = \"Scegli un prodotto qui sopra.\"; ed.append(e); return; }\n    const img = IMGS[cur];\n    const list = document.createElement(\"div\"); list.style.cssText = \"display:flex;flex-direction:column;gap:18px\";\n    for (const sec of SECS) {\n      const isHero = sec.id === \"hero\";\n      const saved = CUTS[cur + \"__\" + sec.id];\n      const okCut = (c) => c && c.asset === img.asset;\n      state[sec.id] = okCut(saved) ? fromRect(img, sec.ar, saved) : { cx: 0.5, cy: 0.42, z: 1 };\n      state[sec.id].dirty = false;\n      // In evidenza: posizione propria per ogni telefono sganciato dalla catena\n      const own = {}, drop = {};\n      if (isHero) for (const p of PHONES) {\n        const c = CUTS[cur + \"__hero@\" + p.id];\n        if (okCut(c)) { own[p.id] = fromRect(img, heroAr(p.dp), c); own[p.id].dirty = false; }\n      }\n      const phoneOf = (id) => PHONES.find((p) => p.id === id);\n      // il \"bersaglio\" delle modifiche: tutti i telefoni (catena) o solo quello scelto\n      const target = () => {\n        if (isHero && own[phone]) return { st: own[phone], ar: heroAr(phoneOf(phone).dp), doc: cur + \"__hero@\" + phone, solo: true };\n        return { st: state[sec.id], ar: sec.ar, doc: cur + \"__\" + sec.id, solo: false };\n      };\n      const rectFor = (pid) => { // rettangolo visto su un telefono\n        if (own[pid]) { const ar = heroAr(phoneOf(pid).dp); clamp(img, ar, own[pid]); return rectOf(img, ar, own[pid]); }\n        clamp(img, sec.ar, state[sec.id]);\n        return shownRect(img, sec, state[sec.id], isHero ? heroAr(phoneOf(pid).dp) : sec.ar);\n      };\n      const paintR = (frame, r) => {\n        const s = frame.clientWidth / (r.x1 - r.x0), im = frame.querySelector(\"img\");\n        im.style.width = img.w + \"px\"; im.style.height = img.h + \"px\";\n        im.style.transform = \"translate(\" + (-r.x0 * s) + \"px,\" + (-r.y0 * s) + \"px) scale(\" + s + \")\";\n      };\n\n      const box = document.createElement(\"section\"); box.className = \"sec\";\n      const head = document.createElement(\"div\"); head.className = \"sec-head\";\n      const h = document.createElement(\"h2\"); h.textContent = sec.name;\n      const badge = document.createElement(\"span\"); badge.className = \"saved\";\n      head.append(h, badge);\n      const rule = document.createElement(\"div\"); rule.className = \"hint\"; rule.textContent = \"Modello: \" + sec.rule;\n      const frame = frameFor(sec, img);\n      const holder = isHero ? document.createElement(\"div\") : null;\n      if (holder) holder.style.overflow = \"hidden\";\n      const view0 = overlay(sec, img, frame);\n      const view = holder ? (holder.append(view0), holder) : view0;\n\n      // telefoni e catena (solo In evidenza)\n      let phoneRow = null, chainBtn = null, chainTxt = null, minis = [];\n      // In evidenza: il riquadro ha le misure vere dell'app (larghezza del telefono − 50, alto 276) con scritte e pulsante\n      // della stessa grandezza, e si rimpicciolisce tutto insieme se non sta nello schermo (prima si rimpiccioliva solo\n      // il riquadro e su \"Pieghevole aperto\" il pulsante restava tagliato)\n      const sizeHero = () => {\n        const p = phoneOf(phone), bw = p.dp - 50, avail = holder ? holder.clientWidth : 0;\n        const k = avail > 0 ? Math.min(1, avail / bw) : 1;\n        frame.style.width = bw + \"px\"; frame.style.height = \"276px\"; frame.style.maxWidth = \"none\"; frame.style.aspectRatio = \"auto\";\n        frame.style.transformOrigin = \"0 0\"; frame.style.transform = k < 1 ? \"scale(\" + k + \")\" : \"\";\n        if (holder) holder.style.height = Math.round(276 * k) + \"px\";\n      };\n      const refreshPhones = () => {\n        if (!phoneRow) return;\n        phoneRow.querySelectorAll(\"button.ph\").forEach((x, i) => {\n          const p = PHONES[i]; x.setAttribute(\"aria-pressed\", String(p.id === phone));\n          x.classList.toggle(\"solo\", !!own[p.id]);\n        });\n        const solo = !!own[phone];\n        chainBtn.innerHTML = solo ? CHAIN_OFF : CHAIN;\n        chainBtn.classList.toggle(\"off\", solo);\n        chainBtn.setAttribute(\"aria-pressed\", String(!solo));\n        chainBtn.setAttribute(\"aria-label\", solo ? \"Ricollega questo telefono agli altri\" : \"Sgancia questo telefono dagli altri\");\n        chainTxt.textContent = solo ? \"Solo \" + phoneOf(phone).name.toLowerCase() + \": le modifiche valgono solo per questo telefono\" : \"Collegati: le modifiche valgono per tutti i telefoni collegati\";\n      };\n      if (isHero) {\n        sizeHero();\n        phoneRow = document.createElement(\"div\"); phoneRow.className = \"phones\"; phoneRow.setAttribute(\"role\", \"group\"); phoneRow.setAttribute(\"aria-label\", \"Larghezza del telefono\");\n        for (const p of PHONES) {\n          const b = document.createElement(\"button\"); b.type = \"button\"; b.className = \"chip ph\";\n          b.append(p.name); const sm = document.createElement(\"small\"); sm.textContent = p.dp + \" dp\"; b.append(sm);\n          b.onclick = () => { phone = p.id; sizeHero(); refreshPhones(); sync(); };\n          phoneRow.append(b);\n        }\n        const chainRow = document.createElement(\"div\"); chainRow.className = \"chain-row\";\n        chainBtn = document.createElement(\"button\"); chainBtn.type = \"button\"; chainBtn.className = \"chain\";\n        chainTxt = document.createElement(\"span\"); chainTxt.className = \"hint\";\n        chainBtn.onclick = () => {\n          if (own[phone]) { // ricollega: torna alla posizione comune; quella propria si cancella al prossimo \"Salva\"\n            if (CUTS[cur + \"__hero@\" + phone]) drop[phone] = true;\n            delete own[phone];\n          } else { // sgancia: parte da quello che si vede ora su questo telefono\n            const ar = heroAr(phoneOf(phone).dp), r = rectFor(phone);\n            own[phone] = fromRect(img, ar, { x0: r.x0 / img.w, y0: r.y0 / img.h, x1: r.x1 / img.w, y1: r.y1 / img.h });\n            own[phone].dirty = !CUTS[cur + \"__hero@\" + phone]; delete drop[phone];\n          }\n          refreshPhones(); sync();\n        };\n        chainRow.append(chainBtn, chainTxt);\n        phoneRow.append(chainRow);\n        const miniRow = document.createElement(\"div\"); miniRow.className = \"minis\";\n        for (const p of PHONES) {\n          const cell = document.createElement(\"div\"); cell.className = \"mini\";\n          const f = document.createElement(\"div\"); f.className = \"frame hero mini-f\";\n          f.style.width = Math.round((p.dp - 50) * 0.42) + \"px\"; f.style.aspectRatio = String(heroAr(p.dp)); f.style.cursor = \"pointer\";\n          f.title = \"Modifica \" + p.name.toLowerCase();\n          const im = document.createElement(\"img\"); im.alt = \"\"; im.draggable = false; im.src = BLOB(img.asset);\n          const fade = document.createElement(\"div\"); fade.className = \"fade\";\n          const nm = document.createElement(\"div\"); nm.className = \"mini-nm\"; nm.textContent = img.name || img.code;\n          f.append(im, fade, nm);\n          f.onclick = () => { phone = p.id; sizeHero(); refreshPhones(); sync(); };\n          const cap = document.createElement(\"div\"); cap.className = \"hint mini-cap\";\n          cell.append(f, cap); miniRow.append(cell); minis.push({ f, p, cap });\n        }\n        box._minis = miniRow;\n      }\n\n      // D-pad e zoom fine\n      // un tocco = 1 pixel dell'immagine originale (tenendo premuto accelera); zoom a passi esatti di 0,01\n      const STEP_PX = 1;\n      const move = (dx, dy) => (k) => { const st = target().st; st.cx -= dx * STEP_PX * k / img.w; st.cy -= dy * STEP_PX * k / img.h; touch(); };\n      const zoom = (d) => (k) => { const st = target().st; st.z = Math.max(1, Math.min(ZMAX, Math.round((st.z + d * 0.01 * k) * 100) / 100)); touch(); };\n      const pad = document.createElement(\"div\"); pad.className = \"pad\"; pad.setAttribute(\"role\", \"group\"); pad.setAttribute(\"aria-label\", \"Sposta l'immagine\");\n      const cells = [null, holdButton(\"▲\", \"Sposta l'immagine su\", move(0, -1)), null,\n        holdButton(\"◀\", \"Sposta l'immagine a sinistra\", move(-1, 0)), null, holdButton(\"▶\", \"Sposta l'immagine a destra\", move(1, 0)),\n        null, holdButton(\"▼\", \"Sposta l'immagine giù\", move(0, 1)), null];\n      const center = document.createElement(\"button\"); center.type = \"button\"; center.className = \"pad-b pad-c\"; center.textContent = \"●\"; center.title = \"Al centro\"; center.setAttribute(\"aria-label\", \"Rimetti al centro\");\n      center.onclick = () => { const st = target().st; st.cx = 0.5; st.cy = 0.5; touch(); };\n      cells[4] = center;\n      cells.forEach((c) => pad.append(c || Object.assign(document.createElement(\"span\"), { className: \"pad-e\" })));\n      const zpad = document.createElement(\"div\"); zpad.className = \"zpad\"; zpad.setAttribute(\"role\", \"group\"); zpad.setAttribute(\"aria-label\", \"Zoom\");\n      const zv = document.createElement(\"span\"); zv.className = \"zv\";\n      zpad.append(holdButton(\"−\", \"Riduci lo zoom\", zoom(-1)), zv, holdButton(\"+\", \"Aumenta lo zoom\", zoom(1)));\n      const rng = document.createElement(\"input\"); rng.type = \"range\"; rng.id = \"z-\" + sec.id; rng.min = \"1\"; rng.max = String(ZMAX); rng.step = \"0.01\"; rng.setAttribute(\"aria-label\", \"Zoom\");\n      const save = document.createElement(\"button\"); save.type = \"button\"; save.className = \"b pri\"; save.textContent = \"Salva\";\n      const tools = document.createElement(\"div\"); tools.className = \"tools\";\n      const right = document.createElement(\"div\"); right.className = \"tools-r\";\n      // indicatore: spostamento dal centro e margini rispetto ai bordi dell'immagine originale, in pixel\n      const meter = document.createElement(\"div\"); meter.className = \"meter\"; meter.setAttribute(\"aria-live\", \"polite\");\n      meter.innerHTML = '<div class=\"m-h\">Spostamento dal centro</div><div class=\"m-move\"></div><div class=\"m-h\">Spazio ai bordi</div><div class=\"m-grid\"><span>◀ <b data-k=\"l\"></b></span><span>▶ <b data-k=\"r\"></b></span><span>▲ <b data-k=\"t\"></b></span><span>▼ <b data-k=\"b\"></b></span></div><div class=\"m-note\"></div>';\n      right.append(zpad, rng, meter, save);\n      tools.append(pad, right);\n\n      const pending = () => { const t = target(); return t.st.dirty || !okCut(CUTS[t.doc]) || Object.keys(drop).length > 0; };\n      const sync = () => {\n        const t = target();\n        clamp(img, t.ar, t.st);\n        rng.value = String(t.st.z); zv.textContent = t.st.z.toFixed(2).replace(\".\", \",\") + \"×\";\n        {\n          const r = isHero ? rectFor(phone) : rectFor(null);\n          const ox = Math.round(img.w / 2 - (r.x0 + r.x1) / 2), oy = Math.round(img.h / 2 - (r.y0 + r.y1) / 2);\n          const hx = ox === 0 ? \"centrata in orizzontale\" : Math.abs(ox) + \" px \" + (ox > 0 ? \"a destra\" : \"a sinistra\");\n          const hy = oy === 0 ? \"centrata in verticale\" : Math.abs(oy) + \" px \" + (oy > 0 ? \"in giù\" : \"in su\");\n          meter.querySelector(\".m-move\").textContent = hx + \" · \" + hy;\n          const v = { l: r.x0, r: img.w - r.x1, t: r.y0, b: img.h - r.y1 };\n          meter.querySelectorAll(\"b[data-k]\").forEach((el) => { el.textContent = Math.max(0, Math.round(v[el.dataset.k])) + \" px\"; });\n          meter.querySelector(\".m-note\").textContent = \"Pixel dell'immagine originale (\" + img.w + \" × \" + img.h + \"); si vede un riquadro di \" + Math.round(r.x1 - r.x0) + \" × \" + Math.round(r.y1 - r.y0) + \". Un tocco sulle frecce = \" + STEP_PX + \" px.\";\n        }\n        paintR(frame, isHero ? rectFor(phone) : rectFor(null));\n        for (const m of minis) {\n          paintR(m.f, rectFor(m.p.id));\n          m.cap.textContent = m.p.name + \" · \" + (own[m.p.id] ? \"posizione propria\" : \"collegato\");\n          m.f.classList.toggle(\"cur\", m.p.id === phone);\n        }\n        if (pending()) { badge.className = \"saved changed\"; badge.textContent = t.st.dirty || Object.keys(drop).length ? \"Da salvare\" : \"Non ancora salvato\"; }\n        else { badge.className = \"saved\"; badge.textContent = t.solo ? \"Salvato per \" + phoneOf(phone).name.toLowerCase() : \"Salvato\"; }\n        save.textContent = t.solo ? \"Salva per \" + phoneOf(phone).name.toLowerCase() : \"Salva\";\n        save.disabled = !db || !pending();\n      };\n      const touch = () => { target().st.dirty = true; sync(); };\n      rng.oninput = () => { target().st.z = Math.round(+rng.value * 100) / 100; touch(); };\n      save.onclick = async () => {\n        const t = target(); clamp(img, t.ar, t.st); const r = rectOf(img, t.ar, t.st);\n        const body = { code: cur, sec: sec.id, asset: img.asset, w: img.w, h: img.h,\n          x0: r.x0 / img.w, y0: r.y0 / img.h, x1: r.x1 / img.w, y1: r.y1 / img.h, cx: t.st.cx, cy: t.st.cy,\n          px: [Math.round(r.x0), Math.round(r.y0), Math.round(r.x1), Math.round(r.y1)], zoom: +t.st.z.toFixed(3), at: new Date().toISOString() };\n        if (t.solo) { body.phone = phone; body.dp = phoneOf(phone).dp; body.ar = +t.ar.toFixed(4); }\n        save.disabled = true; save.textContent = \"Salvo…\";\n        try {\n          for (const pid of Object.keys(drop)) { await db.doc(\"tagli/\" + cur + \"__hero@\" + pid).delete(); delete CUTS[cur + \"__hero@\" + pid]; delete drop[pid]; }\n          await db.doc(\"tagli/\" + t.doc).set(body); t.st.dirty = false; CUTS[t.doc] = body;\n          status(sec.name + \" di \" + cur + (t.solo ? \" salvato solo per \" + phoneOf(phone).name.toLowerCase() + \".\" : \" salvato.\"));\n        } catch (e) { status(\"Non sono riuscito a salvare: \" + (e && e.message || \"errore\") + \". Riprova tra poco.\", true); }\n        sync(); renderChips();\n      };\n\n      // trascinamento e pizzico\n      const pts = new Map(); let last = null, pinch = null;\n      frame.addEventListener(\"pointerdown\", (e) => { frame.setPointerCapture(e.pointerId); pts.set(e.pointerId, { x: e.clientX, y: e.clientY }); frame.classList.add(\"drag\"); last = { x: e.clientX, y: e.clientY }; if (pts.size === 2) { const [a, b] = [...pts.values()]; pinch = { d: Math.hypot(a.x - b.x, a.y - b.y), z: target().st.z }; } });\n      frame.addEventListener(\"pointermove\", (e) => {\n        if (!pts.has(e.pointerId)) return;\n        pts.set(e.pointerId, { x: e.clientX, y: e.clientY });\n        const st = target().st;\n        if (pts.size >= 2 && pinch) { const [a, b] = [...pts.values()]; st.z = Math.max(1, Math.min(ZMAX, pinch.z * Math.hypot(a.x - b.x, a.y - b.y) / pinch.d)); touch(); return; }\n        const r = isHero ? rectFor(phone) : rectFor(null), s = frame.getBoundingClientRect().width / (r.x1 - r.x0);\n        st.cx -= (e.clientX - last.x) / s / img.w; st.cy -= (e.clientY - last.y) / s / img.h;\n        last = { x: e.clientX, y: e.clientY }; touch();\n      });\n      const up = (e) => { pts.delete(e.pointerId); if (pts.size < 2) pinch = null; if (!pts.size) frame.classList.remove(\"drag\"); else { const p = [...pts.values()][0]; last = { x: p.x, y: p.y }; } };\n      frame.addEventListener(\"pointerup\", up); frame.addEventListener(\"pointercancel\", up);\n      frame.addEventListener(\"wheel\", (e) => { e.preventDefault(); const st = target().st; st.z = Math.max(1, Math.min(ZMAX, st.z * Math.exp(-e.deltaY * 0.0015))); touch(); }, { passive: false });\n      frame.addEventListener(\"keydown\", (e) => {\n        const k = e.key;\n        if (k === \"ArrowLeft\") move(-1, 0)(1); else if (k === \"ArrowRight\") move(1, 0)(1);\n        else if (k === \"ArrowUp\") move(0, -1)(1); else if (k === \"ArrowDown\") move(0, 1)(1);\n        else if (k === \"+\" || k === \"=\") zoom(1)(1); else if (k === \"-\") zoom(-1)(1);\n        else return;\n        e.preventDefault();\n      });\n\n      box.append(head, rule);\n      if (phoneRow) box.append(phoneRow);\n      box.append(view, tools);\n      if (box._minis) {\n        const mh = document.createElement(\"div\"); mh.className = \"eyebrow\"; mh.textContent = \"Tutti i telefoni · tocca per modificarne uno\";\n        box.append(mh, box._minis);\n      } else {\n        const same = document.createElement(\"div\"); same.className = \"hint\";\n        same.textContent = \"Questo riquadro ha la stessa forma su tutti i telefoni: cambia solo la grandezza.\";\n        box.append(same);\n      }\n      list.append(box);\n      refreshPhones();\n      const im = frame.querySelector(\"img\");\n      if (im.complete) sync(); else im.onload = sync;\n      for (const m of minis) { const mi = m.f.querySelector(\"img\"); if (!mi.complete) mi.onload = sync; }\n      new ResizeObserver(() => sync()).observe(frame);\n      if (holder) new ResizeObserver(() => { sizeHero(); }).observe(holder);\n      sync();\n    }\n    const tip = document.createElement(\"p\"); tip.className = \"hint\";\n    tip.textContent = \"Trascina con un dito o col mouse, oppure usa le frecce: un tocco sposta di 1 pixel, tenendo premuto continua. Lo zoom si regola con − e + (0,01 a tocco), col cursore o pizzicando. In \\\"In evidenza\\\" la catena tiene tutti i telefoni insieme: sganciala per sistemare solo il telefono scelto. I tagli salvati arrivano nell'app di tutti in pochi minuti.\";\n    list.append(tip);\n    ed.append(list);\n  }\n\n  // ---- caricamento di un'immagine nuova (solo chi può modificare)\n  async function addImage() {\n    const st = $(\"addStatus\");\n    const code = $(\"addCode\").value.trim().toUpperCase().replace(/[^A-Z0-9-]/g, \"\");\n    const name = $(\"addName\").value.trim();\n    const file = $(\"addFile\").files[0];\n    if (!code) { st.textContent = \"Scrivi il codice del prodotto, per esempio EX14.\"; return; }\n    if (!file) { st.textContent = \"Scegli un'immagine dal telefono o dal computer.\"; return; }\n    $(\"addBtn\").disabled = true; st.textContent = \"Carico l'immagine…\";\n    try {\n      const url = URL.createObjectURL(file);\n      const dim = await new Promise((ok, ko) => { const i = new Image(); i.onload = () => ok({ w: i.naturalWidth, h: i.naturalHeight }); i.onerror = ko; i.src = url; });\n      URL.revokeObjectURL(url);\n      const up = await assets.upload(file, code);\n      await db.doc(\"immagini/\" + code).set({ code, name: name || (IMGS[code] && IMGS[code].name) || \"\", asset: up.id, w: up.w || dim.w, h: up.h || dim.h, at: new Date().toISOString() });\n      cur = code; st.textContent = \"Caricata: ora puoi tagliarla.\";\n      $(\"addCode\").value = \"\"; $(\"addName\").value = \"\"; $(\"addFile\").value = \"\";\n    } catch (e) { st.textContent = \"Caricamento non riuscito: \" + (e && e.message || \"errore\") + \".\"; }\n    $(\"addBtn\").disabled = false;\n  }\n\n  // ---- confronto: per serie (prefisso del codice), poi per tipo di banner, con scorrimento a destra\n  const CMP_H = 150;\n  function seriesOf(c) { return (c.match(/^[A-Z]*/) || [\"\"])[0] || \"Altro\"; }\n  function cmpSort(a, b) {\n    const pa = seriesOf(a), pb = seriesOf(b);\n    if (pa !== pb) return pa < pb ? -1 : 1;\n    return a.localeCompare(b, undefined, { numeric: true });\n  }\n  // ritaglio salvato -> miniatura alla stessa altezza; posizione in percentuali (nessuna misura del browser)\n  function cmpCap(w, code, zoom, state) {\n    const cap = document.createElement(\"div\"); cap.className = \"cmp-cap\"; cap.style.width = w + \"px\";\n    // righe fisse: codice, zoom (anche nei riquadri stretti), stato (solo In evidenza)\n    const l1 = document.createElement(\"div\"), b = document.createElement(\"b\"); b.textContent = code; l1.append(b);\n    const l2 = document.createElement(\"div\"); l2.textContent = zoom || \"\\u00a0\";\n    cap.append(l1, l2);\n    if (state !== undefined) { const l2 = document.createElement(\"div\"); l2.className = \"st\"; l2.textContent = state; cap.append(l2); }\n    cap.title = [code, zoom, state].filter(Boolean).join(\" · \");\n    return cap;\n  }\n  function cmpThumb(img, d, code, zoom, state) {\n    const dw = d.x1 - d.x0;\n    const ar = (dw * img.w) / ((d.y1 - d.y0) * img.h);\n    const w = Math.round(CMP_H * ar);\n    const cell = document.createElement(\"div\"); cell.className = \"cmp-cell\";\n    const box = document.createElement(\"div\"); box.className = \"cmp-box\";\n    box.style.width = w + \"px\"; box.style.height = CMP_H + \"px\";\n    const im = document.createElement(\"img\"); im.alt = \"\"; im.draggable = false; im.loading = \"lazy\";\n    im.src = BLOB(img.asset);\n    im.style.width = (100 / dw) + \"%\";\n    im.style.left = (-d.x0 / dw * 100) + \"%\";\n    im.style.top = (-(d.y0 / dw) * (img.h / img.w) * ar * 100) + \"%\";\n    box.append(im);\n    cell.append(box, cmpCap(w, code, zoom, state));\n    return cell;\n  }\n  function cmpEmpty(code, ar, state) {\n    const w = Math.round(CMP_H * ar);\n    const cell = document.createElement(\"div\"); cell.className = \"cmp-cell\";\n    const box = document.createElement(\"div\"); box.className = \"cmp-box none\";\n    box.style.width = w + \"px\"; box.style.height = CMP_H + \"px\";\n    box.textContent = \"non ancora tagliata\";\n    cell.append(box, cmpCap(w, code, \"\", state));\n    return cell;\n  }\n  // zoom di un taglio (frazioni dell'originale) in un riquadro di forma ar: 1 = l'immagine riempie appena il riquadro\n  const zoomOf = (img, d, ar) => viewSize(img, ar, 1).w / ((d.x1 - d.x0) * img.w);\n  const zTxt = (z) => \"zoom \" + z.toFixed(2).replace(\".\", \",\") + \"×\";\n  // taglio comune mostrato su un telefono: stesso centro e stessa altezza, più o meno largo (come l'app, fitRect)\n  function fitFrac(img, d, ar) {\n    const cx = (d.x0 + d.x1) / 2 * img.w, cy = (d.y0 + d.y1) / 2 * img.h;\n    let h = (d.y1 - d.y0) * img.h, w = h * ar;\n    const lim = 2 * Math.min(cx, img.w - cx);\n    if (w > lim) { w = lim; h = w / ar; }\n    return { x0: (cx - w / 2) / img.w, y0: (cy - h / 2) / img.h, x1: (cx + w / 2) / img.w, y1: (cy + h / 2) / img.h };\n  }\n  const heroRow = (p) => ({ name: \"In evidenza · \" + p.name + \" (\" + p.dp + \" dp)\", cells: (c, img, ok) => {\n    const ar = heroAr(p.dp), own = CUTS[c + \"__hero@\" + p.id], com = CUTS[c + \"__hero\"];\n    if (ok(own)) return [cmpThumb(img, own, c, zTxt(zoomOf(img, own, ar)), \"posizione propria\")];\n    // zoom comune, lo stesso che si vede in Taglia (misurato sul riquadro di riferimento, come lo stato dell'editor)\n    if (ok(com)) { const r = fitFrac(img, com, ar); return [cmpThumb(img, r, c, zTxt(zoomOf(img, com, SECS[0].ar)), \"collegato\")]; }\n    return [cmpEmpty(c, ar, \"da fare\")];\n  } });\n  const fixRow = (id, name, ar) => ({ name, cells: (c, img, ok) => {\n    const d = CUTS[c + \"__\" + id];\n    return [ok(d) ? cmpThumb(img, d, c, zTxt(zoomOf(img, d, ar))) : cmpEmpty(c, ar)];\n  } });\n  const CMP_TYPES = [\n    ...PHONES.map(heroRow),\n    fixRow(\"cover\", \"Set da completare\", 65 / 91),\n    fixRow(\"square\", \"All'orizzonte\", 1),\n  ];\n  function renderCompare() {\n    const wrap = $(\"cmp\");\n    if (!wrap) return;\n    wrap.textContent = \"\";\n    const codes = Object.keys(IMGS).sort(cmpSort);\n    if (!codes.length) { const e = document.createElement(\"p\"); e.className = \"hint\"; e.textContent = \"Nessuna immagine ancora.\"; wrap.append(e); return; }\n    const bySeries = new Map();\n    for (const c of codes) { const k = seriesOf(c); if (!bySeries.has(k)) bySeries.set(k, []); bySeries.get(k).push(c); }\n    for (const [cat, list] of bySeries) {\n      const blk = document.createElement(\"section\"); blk.className = \"cmp-series\";\n      const h = document.createElement(\"div\"); h.className = \"cmp-cat\"; h.textContent = \"Serie \" + cat;\n      const cnt = document.createElement(\"small\"); cnt.textContent = list.length + (list.length === 1 ? \" prodotto\" : \" prodotti\");\n      h.append(cnt); blk.append(h);\n      for (const t of CMP_TYPES) {\n        const type = document.createElement(\"div\"); type.className = \"cmp-type\";\n        const nm = document.createElement(\"div\"); nm.className = \"cmp-tname\"; nm.textContent = t.name;\n        const row = document.createElement(\"div\"); row.className = \"cmp-scroll\"; row.tabIndex = 0;\n        row.setAttribute(\"role\", \"group\"); row.setAttribute(\"aria-label\", t.name + \" · serie \" + cat);\n        for (const c of list) { const img = IMGS[c]; const ok = (d) => !!d && d.asset === img.asset; for (const cell of t.cells(c, img, ok)) row.append(cell); }\n        type.append(nm, row); blk.append(type);\n      }\n      wrap.append(blk);\n    }\n  }\n\n  // ---- avvio\n  function showTab(t) {\n    const c = t === \"cmp\";\n    $(\"viewEdit\").hidden = c; $(\"viewCmp\").hidden = !c;\n    $(\"tabEdit\").setAttribute(\"aria-pressed\", String(!c)); $(\"tabCmp\").setAttribute(\"aria-pressed\", String(c));\n  }\n  async function start() {\n    $(\"tabEdit\").onclick = () => showTab(\"edit\"); $(\"tabCmp\").onclick = () => showTab(\"cmp\");\n    renderEditor();\n    if (!window.claude || !window.claude.use) { status(\"Ponte con l'app non disponibile.\", true); return; }\n    db = await window.claude.use(\"db\");\n    if (!db) { status(\"Il salvataggio non è disponibile.\", true); $(\"chips\").textContent = \"\"; return; }\n    assets = await window.claude.use(\"assets\");\n    if (assets) { $(\"addBox\").hidden = false; $(\"addBtn\").onclick = addImage; }\n    let gotImgs = false;\n    const timer = setTimeout(() => { if (!gotImgs) status(\"Le immagini non arrivano ancora: controlla la connessione.\", true); }, 10000);\n    db.collection(\"immagini\").onSnapshot((snap) => {\n      gotImgs = true; if (!snap.metadata.fromCache) { clearTimeout(timer); status(\"\"); }\n      const next = {}; snap.docs.forEach((d) => { const v = d.data(); if (v && v.asset) next[d.id] = Object.assign({ code: d.id }, v); });\n      const changed = !cur || !IMGS[cur] || !next[cur] || IMGS[cur].asset !== (next[cur] && next[cur].asset);\n      IMGS = next;\n      if (!cur || !IMGS[cur]) cur = Object.keys(IMGS).sort()[0] || null;\n      renderChips(); renderCompare(); if (changed) renderEditor();\n    }, (e) => { clearTimeout(timer); status(\"Non riesco a leggere le immagini (\" + e.code + \").\", true); });\n    db.collection(\"tagli\").onSnapshot((snap) => {\n      const next = {}; snap.docs.forEach((d) => { next[d.id] = d.data(); });\n      const first = !Object.keys(CUTS).length;\n      CUTS = next; renderChips(); renderCompare();\n      // al primo arrivo dei tagli salvati ridisegno con quelli; dopo, non tocco quello che si sta regolando\n      if (first && cur) renderEditor();\n    }, (e) => status(\"Non riesco a leggere i tagli salvati (\" + e.code + \").\", true));\n  }\n  start();\n})();\n</script>\n</body>\n</html>\n";
